const now = new Date();
const end = new Date(now);
const start = new Date(now);
start.setDate(start.getDate() - 7);
const fmt = (d) => d.toISOString().slice(0,10);
for (const item of items){
  item.json.startDate = fmt(start);
  item.json.endDate = fmt(end);
}
return items;

// n8n Code node: Group stats + collect sample issues for AI
// Input: merged stream of GitHub Search API items (splitIntoItems = true)
// Output: single item with weekly digest fields and issuesSample[]

function fmt(d) { return d.toISOString().slice(0, 10); }
function clip(s, n = 220){ if (!s) return ''; s = String(s); return s.length > n ? s.slice(0, n) + '…' : s; }

const now = new Date();
const end = new Date(now);
const start = new Date(now);
start.setDate(start.getDate() - 7);

const perType = { bug: 0, task: 0, feature: 0, 'needs-triage': 0 };
const perAuthor = {};
const issuesSample = [];

for (const item of items) {
  const t = item.json.type || 'unknown';
  if (perType[t] !== undefined) perType[t]++;

  const author = item.json.author || 'unknown';
  if (!perAuthor[author]) perAuthor[author] = { bug: 0, task: 0, feature: 0, 'needs-triage': 0, total: 0 };
  if (perAuthor[author][t] !== undefined) perAuthor[author][t]++;
  perAuthor[author].total++;

  if (issuesSample.length < 20) {
    issuesSample.push({
      type: t,
      author,
      title: item.json.title || '',
      body: clip(item.json.body || ''),
      number: item.json.number || null,
      url: item.json.url || item.json.html_url || ''
    });
  }
}

const total = perType.bug + perType.task + perType.feature + perType['needs-triage'];

return [{ json: { perType, perAuthor, total, startDate: fmt(start), endDate: fmt(end), issuesSample } }];

// n8n Code node: Compute Δ & HTML (single item result)
// Inputs:
//  - Input 0: текущая неделя из Group stats (perType/perAuthor как объект; может прийти строкой)
//  - Input 1: последняя запись из Data Table (строки JSON)
// Output (строго 1 item):
//  {
//    table: 'weekly',
//    startDate, endDate,
//    perType: stringified JSON,
//    perAuthor: stringified JSON,
//    perTypeObj: object,
//    perAuthorObj: object,
//    total: number,
//    delta: { bug, task, feature, 'needs-triage', total },
//    issuesSample: [...],
//    html: string (таблицы + список issues)
//  }

function parseJSONDeep(value, fallback, maxDepth = 2) {
  if (value == null) return fallback;
  let v = value;
  for (let i = 0; i < maxDepth; i++) {
    if (typeof v === 'string') {
      try { v = JSON.parse(v); continue; } catch { break; }
    }
    break;
  }
  if (v == null) return fallback;
  if (typeof v === 'object') return v;
  return fallback;
}

// Heuristics to distinguish current vs previous when оба приходят в один вход (после Merge)
function looksLikePrev(obj) {
  if (!obj || typeof obj !== 'object') return false;
  // Признаки записи из DataTable: есть id/createdAt/updatedAt, perType как строка, нет issuesSample
  if (typeof obj.id !== 'undefined') return true;
  if (typeof obj.createdAt === 'string' || typeof obj.updatedAt === 'string') return true;
  if (typeof obj.perType === 'string' && !Array.isArray(obj.issuesSample)) return true;
  return false;
}

// Determine current and previous payloads
let cur = (items[0] && items[0].json) || {};
let prevRow = null;

if (items.length >= 2) {
  const a = items[0]?.json || {};
  const b = items[1]?.json || {};
  const aPrev = looksLikePrev(a);
  const bPrev = looksLikePrev(b);
  if (aPrev && !bPrev) { prevRow = a; cur = b; }
  else if (!aPrev && bPrev) { prevRow = b; cur = a; }
  else {
    // неоднозначно: считаем items[0] текущим, items[1] прошлым
    cur = a; prevRow = b;
  }
} else {
  // Совместимость со старой схемой: прошлую неделю берём из второго входа
  const prevItems = $input.all(1);
  prevRow = prevItems[0]?.json || null;
}

const issuesSample = Array.isArray(cur.issuesSample) ? cur.issuesSample : [];

// Normalize current aggregates (may arrive as object or JSON string)
// Prefer explicit object fields if предыдущая нода их передаёт (perTypeObj/perAuthorObj)
const curPerType = (cur.perTypeObj && typeof cur.perTypeObj === 'object')
  ? cur.perTypeObj
  : (parseJSONDeep(cur.perType, cur.perType) || { bug: 0, task: 0, feature: 0, 'needs-triage': 0 });
const curPerAuthor = (cur.perAuthorObj && typeof cur.perAuthorObj === 'object')
  ? cur.perAuthorObj
  : (parseJSONDeep(cur.perAuthor, cur.perAuthor) || {});
const curTotal = Number(cur.total ?? (curPerType.bug||0) + (curPerType.task||0) + (curPerType.feature||0) + (curPerType['needs-triage']||0));

// Normalize previous aggregates (stored as JSON strings in DB)
const prevPerType = prevRow ? parseJSONDeep(prevRow.perType, null) : null;
const prevTotal = prevRow ? Number(prevRow.total || 0) : null;

// Compute delta safely
const delta = (prevPerType && typeof prevPerType === 'object') ? {
  bug: (curPerType.bug || 0) - (prevPerType.bug || 0),
  task: (curPerType.task || 0) - (prevPerType.task || 0),
  feature: (curPerType.feature || 0) - (prevPerType.feature || 0),
  'needs-triage': (curPerType['needs-triage'] || 0) - (prevPerType['needs-triage'] || 0),
  total: curTotal - (prevTotal || 0),
} : { bug: null, task: null, feature: null, 'needs-triage': null, total: null };

// HTML tables
const typeRows = Object.entries(curPerType)
  .map(([k, v]) => {
    const d = delta[k];
    const dStr = (d === null || d === undefined) ? 'N/A' : `${d >= 0 ? '+' : ''}${d}`;
    return `<tr><td>${k}</td><td>${v}</td><td>${dStr}</td></tr>`;
  })
  .join('');

const authorRows = Object.entries(curPerAuthor)
  .map(([author, c]) => `<tr><td>${author}</td><td>${c.bug||0}</td><td>${c.task||0}</td><td>${c.feature||0}</td><td>${c['needs-triage']||0}</td><td>${c.total||0}</td></tr>`)
  .join('');

const issuesList = issuesSample.map(i => {
  const safe = (s) => String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const title = safe(i.title || '(no title)');
  const body = safe((i.body || '').split('\n').slice(0,4).join(' '));
  const url = safe(i.url || '');
  const t = safe(i.type || 'unknown');
  return `<li>[${t}] <a href="${url}">${title}</a> — ${body}</li>`;
}).join('');

const html = `
  <h2>Weekly Issue Stats (${cur.startDate} .. ${cur.endDate})</h2>
  <h3>By type</h3>
  <table border=1 cellpadding=6 cellspacing=0>
    <thead><tr><th>Type</th><th>Count</th><th>Δ</th></tr></thead>
    <tbody>${typeRows}</tbody>
  </table>
  <h3>By author</h3>
  <table border=1 cellpadding=6 cellspacing=0>
    <thead><tr><th>Author</th><th>bug</th><th>task</th><th>feature</th><th>needs-triage</th><th>Total</th></tr></thead>
    <tbody>${authorRows}</tbody>
  </table>
  <h3>Issues sample</h3>
  <ol>${issuesList}</ol>
`;

// Prepare string fields for DB
const perTypeStr = JSON.stringify(curPerType);
const perAuthorStr = JSON.stringify(curPerAuthor);

return [{ json: {
  table: 'weekly',
  startDate: cur.startDate,
  endDate: cur.endDate,
  // Strings for DB
  perType: perTypeStr,
  perAuthor: perAuthorStr,
  // Objects for AI/logic
  perTypeObj: curPerType,
  perAuthorObj: curPerAuthor,
  total: curTotal,
  delta,
  issuesSample,
  html,
}}];

// n8n Code node: Build AI Context with issues
// Входы:
//  - Input 0: результат из compute_delta_and_html_strings (perTypeObj, perAuthorObj, delta, html, issuesSample, даты)
//  - (опционально) Input 1: результат Group stats (если нужно больше контекста)
// Выход: один элемент с полем aiContext (string) + пробрасываем html, даты и агрегаты

function lineSafe(s) {
  if (s == null) return '';
  s = String(s);
  return s.replace(/\r/g, '').replace(/\n/g, ' ');
}

const cur = (items[0] && items[0].json) || {};
const perType = cur.perTypeObj || cur.perType || {};
const perAuthor = cur.perAuthorObj || cur.perAuthor || {};
const delta = cur.delta || {};
const total = Number(cur.total || 0);
const startDate = cur.startDate;
const endDate = cur.endDate;
const issuesSample = Array.isArray(cur.issuesSample) ? cur.issuesSample : [];

const typesSummary = `bug=${perType.bug||0}, task=${perType.task||0}, feature=${perType.feature||0}, needs-triage=${perType['needs-triage']||0}, total=${total}`;
const deltaSummary = (delta.total === null || delta.total === undefined)
  ? 'N/A (нет прошлой недели в БД)'
  : `Δ total=${delta.total}; bug=${delta.bug}, task=${delta.task}, feature=${delta.feature}, needs-triage=${delta['needs-triage']}`;

// Топ авторов по total
const authorsSorted = Object.entries(perAuthor)
  .sort((a,b)=> (b[1]?.total||0) - (a[1]?.total||0))
  .slice(0,5)
  .map(([name,c])=> `${name}: total=${c.total||0} (bug=${c.bug||0}, task=${c.task||0}, feature=${c.feature||0}, needs-triage=${c['needs-triage']||0})`)
  .join('; ');

// Сформируем список примеров issues: [type] title — first 220 chars of body
const issueLines = issuesSample.map(i => {
  const t = i.type || 'unknown';
  const title = lineSafe(i.title || '(no title)');
  const body = lineSafe(i.body || '');
  return `[${t}] ${title} — ${body}`;
});

const aiContext = [
  `Период: ${startDate} .. ${endDate}`,
  `Типы: ${typesSummary}`,
  `Изменения: ${deltaSummary}`,
  `Топ авторов: ${authorsSorted}`,
  `Примеры issues:`,
  ...issueLines,
].join('\n');

return [{ json: {
  startDate, endDate,
  perTypeObj: perType,
  perAuthorObj: perAuthor,
  perType: cur.perType,         // строка — если нужно в письме или записи
  perAuthor: cur.perAuthor,     // строка — если нужно в письме или записи
  total, delta,
  html: cur.html,
  aiContext,
}}];

// Assemble final HTML with AI comment (supports merged single-input or two-inputs)

function isObject(v){ return v && typeof v === 'object'; }
function pickAI(obj){ if (!isObject(obj)) return false; return Boolean(obj.text || obj.output || obj.message); }
function pickBase(obj){ if (!isObject(obj)) return false; return Boolean(obj.html || obj.perType || obj.perTypeObj || obj.table === 'weekly'); }

// Try merged single-input first (items array may contain base+ai)
const arr = items.map(it => it?.json || {});
let base = arr.find(pickBase) || {};
let ai = arr.find(pickAI) || {};

// Fallback: if AI not found in same input, try secondary input (old wiring)
if (!pickAI(ai)) {
  const aiItems = $input.all(1);
  ai = (aiItems[0] && aiItems[0].json) || {};
}

const aiText = ai.text || ai.output || ai.message || '';
const addAi = aiText ? `\n  <h3>AI-комментарий недели</h3>\n  <div>${String(aiText).replaceAll('\n','<br>')}</div>\n` : '';
const htmlWithAi = (base.html || '') + addAi;

return [{ json: { ...base, aiComment: aiText, htmlWithAi } }];

const annotateType = 'bug';
function extractAuthor(obj) { const u = obj.user || {}; return u.login || 'unknown'; }
function pick(issue){ return {
  type: annotateType,
  author: extractAuthor(issue),
  title: issue.title || '',
  body: issue.body || '',
  number: issue.number || null,
  url: issue.html_url || issue.url || ''
}; }
let out = [];
if (items.length === 1 && Array.isArray(items[0].json?.items)) {
  for (const issue of items[0].json.items) { out.push({ json: pick(issue) }); }
}
return out;

